import Model from 'flarum/common/Model';
export default class TrustLevel extends Model {
  name = (() => Model.attribute('name'))();
  condition = (() => Model.attribute('conditions'))();
  icon = (() => Model.attribute('icon'))();
  level = (() => Model.attribute('level'))();
  group_id = (() => Model.attribute('group_id'))();
  allow_downgrade = (() => Model.attribute('allow_downgrade'))();
  downgrade_grace_days = (() => Model.attribute('downgrade_grace_days'))();
  manual_only = (() => Model.attribute('manual_only'))();
  next = (() => Model.hasOne('next'))();
}
flarum.reg.add('xypp-trust-levels', 'common/models/TrustLevel', TrustLevel);